import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Reuse and review runtime variables","description":"","frontmatter":{"title":"Reuse and review runtime variables","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","order":40},"headers":[],"relativePath":"en/user/automations/variables.md","filePath":"en/user/automations/variables.md","lastUpdated":1794591482000}'),r={name:"en/user/automations/variables.md"};function o(n,e,l,d,c,u){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Reuse and review runtime variables <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;Reuse and review runtime variables {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Change a shared value once and reuse it in several actions. You need <strong>Automations → Variables</strong> and a host that supports the relevant variable operations. Typed editing and reviewed Cloud operations appear according to host capabilities; local saving does not require uploading.</p><h2 id="save-a-local-value" tabindex="-1">Save a local value <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;Save a local value {#save-a-local-value}&quot;">​</a></h2><ol><li>Add a variable named <code>showLabel</code>. Keys start with a letter or underscore and may contain letters, digits, dots, underscores and hyphens, up to <code>64</code> characters. Avoid duplicate keys.</li><li>Where typed editing is available, choose text and enter <code>Evening show</code>. Other supported kinds are number, boolean, list and secret. Lists use a JSON array of strings, such as <code>[&quot;red&quot;, &quot;blue&quot;]</code>.</li><li>Select <strong>Save</strong>. A revision conflict means the saved collection changed; reload and review your intended edit against it.</li><li>Use the saved value in a templated action field:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Test a log-only action to inspect the rendered text. Change <code>showLabel</code>, save again and run a new test. Existing action definitions can reuse the updated value without re-importing a template.</li></ol><p>Template <code>params</code> are substituted when applying a template; <code>globals</code> are read at execution. A missing runtime key renders as empty text, so verify spelling before using it in a destination or identifier. Use the field&#39;s variable suggestions for event paths appropriate to its trigger.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Review Cloud changes separately <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;Review Cloud changes separately {#review-cloud-changes-separately}&quot;">​</a></h2><p>The Variables <strong>Changes</strong> control has native reviewed send, fetch, apply/adopt and withdraw operations when supported. Save local edits first, select a comparison, inspect its type and value, and choose the intended direction explicitly. Fetching a Cloud candidate is separate from applying it locally. Withdrawing a shared value is separate from deleting a local row.</p><p>Secret or blocked values are masked in comparisons and cannot be sent through this reviewed path. Never turn a secret into ordinary text merely to bypass that block.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Expected result, status and recovery {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Local variables and capability-gated reviewed sharing are available; saving locally never uploads automatically. Invalid keys, invalid typed values and stale revisions block saving. Correct the highlighted field or reload before retrying. For account failures see <a href="./../cloud/account.html">Cloud account</a>; for comparison behavior see <a href="./../cloud/changes.html">Changes</a>.</p>',13)])])}const v=a(r,[["render",o]]);export{h as __pageData,v as default};
